66: /* Add the inverse of the (current) solution to the clauses.
67:    This function is essentially the same as the function blocksol in app.c
68:    in the picosat source. */
69: static int blocksol(PicoSAT *picosat, signed char *mem)
70: {
71:     int max_idx, i;
72: 
73:     if (mem == NULL) {
74:         // caller must allocate picosat_variables(it->picosat) + 1 bytes
75:         return -1;
76:     }
77: 
78:     max_idx = picosat_variables(picosat);
79: 
80:     for (i = 1; i <= max_idx; i++)
81:         mem[i] = (picosat_deref(picosat, i) > 0) ? 1 : -1;
82: 
83:     for (i = 1; i <= max_idx; i++)
84:         picosat_add(picosat, (mem[i] < 0) ? i : -i);
85: 
86:     picosat_add(picosat, 0);
87:     return 0;
88: }
89: 
90: static int add_clause(PicoSAT *picosat, PyObject *clause)
91: {
92:     PyObject *iterator;         /* each clause is an iterable of literals */
93:     PyObject *lit;              /* the literals are integers */
94:     int v;
95: 
96:     iterator = PyObject_GetIter(clause);
97:     if (iterator == NULL)
98:         return -1;
99: 
100:     while ((lit = PyIter_Next(iterator)) != NULL) {
101:         if (!IS_INT(lit))  {
102:             Py_DECREF(lit);
103:             Py_DECREF(iterator);
104:             PyErr_SetString(PyExc_TypeError, "integer expected");
105:             return -1;
106:         }
107:         v = PyLong_AsLong(lit);
108:         Py_DECREF(lit);
109:         if (v == 0) {
110:             Py_DECREF(iterator);
111:             PyErr_SetString(PyExc_ValueError, "non-zero integer expected");
112:             return -1;
113:         }
114:         picosat_add(picosat, v);
115:     }
116:     Py_DECREF(iterator);
117:     if (PyErr_Occurred())
118:         return -1;
119:     picosat_add(picosat, 0);
120:     return 0;
121: }
122: 
123: static int add_clauses(PicoSAT *picosat, PyObject *clauses)
124: {
125:     PyObject *iterator;       /* clauses can be any iterable */
126:     PyObject *item;           /* each clause is an iterable of integers */
127: 
128:     iterator = PyObject_GetIter(clauses);
129:     if (iterator == NULL)
130:         return -1;
131: 
132:     while ((item = PyIter_Next(iterator)) != NULL) {
133:         if (add_clause(picosat, item) < 0) {
134:             Py_DECREF(item);
135:             Py_DECREF(iterator);
136:             return -1;
137:         }
138:         Py_DECREF(item);
139:     }
140:     Py_DECREF(iterator);
141:     if (PyErr_Occurred())
142:         return -1;
143:     return 0;
144: }
145: 
146: static PicoSAT* setup_picosat(PyObject *args, PyObject *kwds)
147: {
148:     PicoSAT *picosat;
149:     PyObject *clauses;          /* iterable of clauses */
150:     int vars = -1, verbose = 0;
151:     unsigned long long prop_limit = 0;
152:     static char* kwlist[] = {"clauses",
153:                              "vars", "verbose", "prop_limit", NULL};
154: 
155:     if (!PyArg_ParseTupleAndKeywords(args, kwds, "O|iiK:(iter)solve", kwlist,
156:                                      &clauses,
157:                                      &vars, &verbose, &prop_limit))
158:         return NULL;
159: 
160: #if defined(WITH_PYMEM)
161:     picosat = picosat_minit(NULL, py_malloc, py_realloc, py_free);
162: #else
163:     picosat = picosat_init();
164: #endif
165:     picosat_set_verbosity(picosat, verbose);
166:     if (vars != -1)
167:         picosat_adjust(picosat, vars);
168: 
169:     if (prop_limit)
170:         picosat_set_propagation_limit(picosat, prop_limit);
171: 
172:     if (add_clauses(picosat, clauses) < 0) {
173:         picosat_reset(picosat);
174:         return NULL;
175:     }
176: 
177:     if (verbose >= 2)
178:         picosat_print(picosat, stdout);
179: 
180:     return picosat;
181: }
