183: /* read the solution from the picosat object and return a Python list */
184: static PyObject* get_solution(PicoSAT *picosat)
185: {
186:     PyObject *list;
187:     int max_idx, i, v;
188: 
189:     max_idx = picosat_variables(picosat);
190:     list = PyList_New((Py_ssize_t) max_idx);
191:     if (list == NULL) {
192:         picosat_reset(picosat);
193:         return NULL;
194:     }
195:     for (i = 1; i <= max_idx; i++) {
196:         v = picosat_deref(picosat, i);
197:         assert(v == -1 || v == 1);
198:         if (PyList_SetItem(list, (Py_ssize_t) (i - 1),
199:                            PyInt_FromLong((long) (v * i))) < 0) {
200:             Py_DECREF(list);
201:             picosat_reset(picosat);
202:             return NULL;
203:         }
204:     }
205:     return list;
206: }
207: 
208: static PyObject* solve(PyObject *self, PyObject *args, PyObject *kwds)
209: {
210:     PicoSAT *picosat;
211:     PyObject *result = NULL;    /* return value */
212:     int res;
213: 
214:     picosat = setup_picosat(args, kwds);
215:     if (picosat == NULL)
216:         return NULL;
217: 
218:     Py_BEGIN_ALLOW_THREADS      /* release GIL */
219:     res = picosat_sat(picosat, -1);
220:     Py_END_ALLOW_THREADS
221: 
222:     switch (res) {
223:     case PICOSAT_SATISFIABLE:
224:         result = get_solution(picosat);
225:         break;
226: 
227:     case PICOSAT_UNSATISFIABLE:
228:         result = PyUnicode_FromString("UNSAT");
229:         break;
230: 
231:     case PICOSAT_UNKNOWN:
232:         result = PyUnicode_FromString("UNKNOWN");
233:         break;
234: 
235:     default:
236:         PyErr_Format(PyExc_SystemError, "picosat return value: %d", res);
237:     }
238: 
239:     picosat_reset(picosat);
240:     return result;
241: }
