262: static PyObject* itersolve(PyObject *self, PyObject *args, PyObject *kwds)
263: {
264:     soliterobject *it;          /* iterator to be returned */
265: 
266:     it = PyObject_GC_New(soliterobject, &SolIter_Type);
267:     if (it == NULL)
268:         return NULL;
269: 
270:     it->picosat = setup_picosat(args, kwds);
271:     if (it->picosat == NULL)
272:         return NULL;
273: 
274:     it->mem = PyMem_Calloc(picosat_variables(it->picosat) + 1, 1);
275:     if (it->mem == NULL) {
276:         PyErr_NoMemory();
277:         return NULL;
278:     }
279: 
280:     PyObject_GC_Track(it);
281:     return (PyObject *) it;
282: }
