284: PyDoc_STRVAR(itersolve_doc,
285: "itersolve(clauses [, kwargs]) -> iterator\n\
286: \n\
287: Solve the SAT problem for the clauses, and return an iterator over\n\
288: the solutions (which are lists of integers).\n\
289: Please see " PYCOSAT_URL " for more details.");
290: 
291: static PyObject* soliter_next(soliterobject *it)
292: {
293:     PyObject *result = NULL;    /* return value */
294:     int res;
295: 
296:     assert(SolIter_Check(it));
297: 
298:     Py_BEGIN_ALLOW_THREADS      /* release GIL */
299:     res = picosat_sat(it->picosat, -1);
300:     Py_END_ALLOW_THREADS
301: 
302:     switch (res) {
303:     case PICOSAT_SATISFIABLE:
304:         result = get_solution(it->picosat);
305:         if (result == NULL) {
306:             PyErr_SetString(PyExc_SystemError, "failed to create list");
307:             return NULL;
308:         }
309:         /* add inverse solution to the clauses, for next iteration */
310:         if (blocksol(it->picosat, it->mem) < 0)
311:             return NULL;
312:         break;
313: 
314:     case PICOSAT_UNSATISFIABLE:
315:     case PICOSAT_UNKNOWN:
316:         /* no more solutions -- stop iteration */
317:         break;
318: 
319:     default:
320:         PyErr_Format(PyExc_SystemError, "picosat return value: %d", res);
321:     }
322:     return result;
323: }
