325: static void soliter_dealloc(soliterobject *it)
326: {
327:     PyObject_GC_UnTrack(it);
328:     if (it->mem)
329:         PyMem_Free(it->mem);
330:     picosat_reset(it->picosat);
331:     PyObject_GC_Del(it);
332: }
